from fastapi import FastAPI, APIRouter
from fastapi.routing import APIRoute, _IncludedRouter

app = FastAPI()

router = APIRouter()

@router.get("/router-limited", rate_limit="200/day")
def router_limited():
    return {"ok": True}

app.include_router(router)

# Look at the routes in the app
for route in app.routes:
    print(type(route).__name__, ":", route)
    if isinstance(route, _IncludedRouter):
        for r in route.routes:
            print("  inner:", type(r).__name__, r)
            if hasattr(r, 'rate_limit'):
                print("    rate_limit:", r.rate_limit)
    elif isinstance(route, APIRoute):
        print("  rate_limit:", route.rate_limit)
EOF

